from lib import *
S = SS('l58')
steps = [
    step("本机 git 没有设置 protocol.version(git config --get 没有输出),但 clone 的第一行跟踪就是 version 2:2.26 起默认使用协议 v2。服务端先报一段能力广告:version 2、agent=git/2.54.0-Darwin、ls-refs=unborn、fetch=shallow wait-for-done、server-option、object-format=sha1,0000 结束——广告里不再列出 ref。然后客户端发 command=ls-refs(带 agent、object-format,0001 分隔,再是 peel、symrefs、unborn 和 ref-prefix refs/heads/、ref-prefix refs/tags/ 等参数)去要 ref,而不是服务端一开口就倒出所有 ref。", t=tl(S(1)), mark=lidx(S(1), 'version 2', 'clone> command=ls-refs', 'ref-prefix refs/heads/'), done=lidx(S(1), 'ls-refs=unborn', 'fetch=shallow', 'object-format=sha1'), kv=KV([['v2 的广告', '只有能力,没有 ref'], ['ls-refs', '客户端按需要请求 ref(可带 ref-prefix)'], ['0001', 'delim-pkt:分隔命令和参数']], ['ls-refs'])),
    step("v2 把工作拆成命令。git fetch origin main:先 command=ls-refs,参数里有 ref-prefix main、refs/main、refs/tags/main、refs/heads/main、refs/remotes/main … 和 refs/tags/(客户端把“main”展开成 git 会尝试的所有可能的 ref 名),服务端只返回匹配这些前缀的 ref。再 command=fetch:thin-pack、no-progress、ofs-delta、want <sha>、have <sha>、0000;服务端回 acknowledgments / ACK / ready / 0001 / packfile,然后发 pack。同样是 want 和 have,只是外面包了 command= 的信封。", t=tl(S(2)), mark=lidx(S(2), 'ref-prefix refs/heads/main', 'fetch> command=fetch', 'fetch> want', 'fetch< ready', 'fetch< packfile'), done=lidx(S(2), 'fetch> command=ls-refs', 'fetch> have', 'fetch< acknowledgments'), kv=KV([['command=ls-refs', '列 ref,可过滤'], ['command=fetch', 'want / have → pack'], ['ref-prefix', '只要这些前缀的 ref']], ['ref-prefix'])),
    step("有 5000 个 tag 的远程,fetch 一个分支(--no-tags origin main):v0 下服务端发出 5007 行,其中 ref 行 5002 行——不管你要什么都先把全部 ref 倒给你,客户端收到 5006 行;v2 下服务端只发出 15 行,其中 ref 行 1 行,客户端收到 14 行——只返回被 ref-prefix 过滤的那个 main。ref 很多的仓库(大量 tag、PR 分支)上,v2 省掉了绝大部分流量。", t=tl(S(3)), mark=lidx(S(3), 'v2:服务端发出', 'v0:服务端发出'), done=lidx(S(3), '5002 行', '1 行'), b=bars([['v0:服务端发出', 5007, '5007 行'], ['v2:服务端发出', 15, '15 行']], 5007, mark=[1], done=[0]), kv=KV([['v0', '每次先倒出全部 ref'], ['v2', '只返回请求的前缀'], ['5000 个 tag', '5007 行 vs 15 行']], ['v2'])),
    step("什么也没变的 fetch:v0 仍然收到完整的 ref 列表,跟踪 10008 行(服务端 5000 多行加上客户端读到的同样内容),want 0 条;v2 的跟踪只有 48 行,一次 ls-refs(只要 main 相关前缀),没有 fetch 命令,也没有 want。空操作的 fetch 在 v2 下几乎没有开销。", t=tl(S(4)), mark=lidx(S(4), 'v0:跟踪 10008 行', 'v2:跟踪 48 行'), done=lidx(S(4), 'want 0 条'), b=bars([['v0:跟踪行数', 10008, '10008'], ['v2:跟踪行数', 48, '48']], 10008, mark=[1], done=[0]), kv=KV([['v0', '10008 行'], ['v2', '48 行,一次 ls-refs'], ['无变化', '没有 fetch 命令']], ['v2'])),
    step("v2 服务端的原始广告(GIT_PROTOCOL=version=2 调 upload-pack --advertise-refs):version 2、agent、ls-refs=unborn、fetch=shallow wait-for-done、server-option、object-format=sha1,最后一个 0000 flush。每行是一个能力或命令;命令后面的 =… 是这个命令支持的特性(fetch 支持 shallow 与 wait-for-done,ls-refs 支持 unborn)。客户端据此决定能发哪些命令。", t=tl(S(5)), mark=lidx(S(5), 'version 2', 'ls-refs=unborn', 'fetch=shallow wait-for-done'), done=lidx(S(5), 'agent=', 'server-option', 'object-format=sha1', '0000'), kv=KV([['version 2', '协议版本'], ['ls-refs / fetch', '支持的命令及特性'], ['object-format', 'sha1 / sha256']], ['ls-refs / fetch'])),
]
A = mkarti('l58', 58, 'Git,协议 v2,ls-refs,GIT_TRACE_PACKET,真实验证,动画演示',
    '实测协议 v2 与 v0:本机 git 默认 v2;v2 的服务端广告只有能力,ref 由客户端用 command=ls-refs(可带 ref-prefix)按需请求,再用 command=fetch 取对象;有 5000 个 tag 的远程 fetch 一个分支时,v0 服务端发出 5007 行(5002 个 ref),v2 只发 15 行(1 个 ref);无变化的 fetch 跟踪行数 10008 对 48。',
    'git 协议 v2 到底改进了什么?为什么 2.26 起默认启用?这篇用 GIT_TRACE_PACKET 对比 v0 和 v2:一次 clone 的交互、ls-refs 与 fetch 两个命令、有 5000 个 tag 的仓库里 fetch 一个分支的开销,以及什么也没变的 fetch 的开销。',
    [('5007 → 15', '5000 个 tag 的远程,fetch 一个分支时 v0 与 v2 下服务端发出的 pkt-line 行数'), ('10008 → 48', '什么也没变的 fetch,v0 与 v2 的 packet 跟踪行数'), ('ls-refs + fetch', 'v2 把“列 ref”和“取对象”拆成两条命令')],
    [('v0 的问题', '<p>v0 服务端一连上就把所有 ref 倒出来,客户端要的也许只是一个分支。仓库有几千个 tag 或 PR 分支时,每次 fetch 都要先收这一大堆,哪怕什么都没变。</p>'),
     ('v2 的做法', '<p>v2 先广告能力(没有 ref),客户端再发 <code>command=ls-refs</code>,并用 <code>ref-prefix</code> 说明只要哪些前缀(<code>git fetch origin main</code> 会展开成 main、refs/heads/main、refs/tags/main 等候选),服务端只返回这些。</p>'),
     ('fetch 命令', '<p>取对象由 <code>command=fetch</code> 完成:参数里是 want、have(和 v0 一样),服务端回 acknowledgments / ready,然后是 packfile。命令之间用 <code>0001</code>(delim-pkt)分隔参数,<code>0000</code> 结束。</p>'),
     ('省多少', '<p>5000 个 tag 的远程上 fetch 一个分支:v0 服务端发出 5007 行(5002 个 ref),v2 只发 15 行(1 个 ref);无变化的 fetch 跟踪行数从 10008 降到 48。</p>'),
     ('服务端广告', '<p>v2 服务端的广告很短:version、agent、ls-refs=unborn、fetch=shallow wait-for-done、server-option、object-format=sha1,然后是 flush。</p>')],
    steps,
    [ENV_I_GIT + '。服务端是本机裸仓库(file://,没有走网络);v0 用 -c protocol.version=0 强制;5000 个 tag 由 git update-ref --stdin 批量创建;“省多少”以 pkt-line 行数衡量,不是网络字节数;跟踪里的 hash 做了替换',
     '没有验证:真实网络(ssh、smart HTTP)上的字节数与耗时;客户端对 v2 服务端的降级(服务器只支持 v0 时);protocol.version=1;server-option 的使用;object-info 命令;partial clone 下 v2 的 filter 参数(见 partial clone 一篇)'],
    '协议 v2 与 v0')
